void DecorativeTrackerMergerNode::mainObjectsCallback(
  const TrackedObjects::ConstSharedPtr & main_objects)
{
  stop_watch_ptr_->toc("processing_time", true);
  stop_watch_ptr_->toc("delay_main_objects", true);
  diagnostics_interface_ptr_->clear();

  // check if main objects is empty and duration
  if (main_objects->objects.empty() && is_empty_previous_main_objects_) {
    is_empty_previous_main_objects_ = true;
  } else if (main_objects->objects.empty() && !is_empty_previous_main_objects_) {
    stop_watch_ptr_->toc("duration_empty_main_objects", true);
    is_empty_previous_main_objects_ = true;
  } else {
    is_empty_previous_main_objects_ = false;
  }

  /* transform to target merge coordinate */
  TrackedObjects transformed_objects;
  if (!autoware::object_recognition_utils::transformObjects(
        *main_objects, merge_frame_id_, tf_buffer_, transformed_objects)) {
    return;
  }
  TrackedObjects::ConstSharedPtr transformed_main_objects =
    std::make_shared<TrackedObjects>(transformed_objects);

  // try to merge sub object
  if (!sub_objects_buffer_.empty()) {
    // get interpolated sub objects
    // get newest sub objects which timestamp is earlier to main objects
    TrackedObjects::ConstSharedPtr closest_time_sub_objects;
    TrackedObjects::ConstSharedPtr closest_time_sub_objects_later;
    for (const auto & sub_object : sub_objects_buffer_) {
      if (getUnixTime(sub_object->header) < getUnixTime(transformed_main_objects->header)) {
        closest_time_sub_objects = sub_object;
      } else {
        closest_time_sub_objects_later = sub_object;
        break;
      }
    }
    // get delay compensated sub objects
    const auto interpolated_sub_objects = interpolateObjectState(
      closest_time_sub_objects, closest_time_sub_objects_later, transformed_main_objects->header);
    if (interpolated_sub_objects.has_value()) {
      // Merge sub objects
      const auto interp_sub_objs = interpolated_sub_objects.value();
      debug_object_pub_->publish(interp_sub_objs);
      this->decorativeMerger(
        sub_sensor_type_, std::make_shared<TrackedObjects>(interpolated_sub_objects.value()));
    } else {
      RCLCPP_DEBUG(this->get_logger(), "interpolated_sub_objects is null");
    }
  }

  // try to merge main object
  this->decorativeMerger(main_sensor_type_, transformed_main_objects);
  const auto & tracked_objects = getTrackedObjects(transformed_main_objects->header);
  merged_object_pub_->publish(tracked_objects);

  // update diagnostics
  updateDiagnostics();

  published_time_publisher_->publish_if_subscribed(
    merged_object_pub_, tracked_objects.header.stamp);
  processing_time_publisher_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
    "debug/cyclic_time_ms", stop_watch_ptr_->toc("cyclic_time", true));
  processing_time_publisher_->publish<autoware_internal_debug_msgs::msg::Float64Stamped>(
    "debug/processing_time_ms", stop_watch_ptr_->toc("processing_time", true));
  diagnostics_interface_ptr_->publish(tracked_objects.header.stamp);
}

bool transformObjects(
  const T & input_msg, const std::string & target_frame_id, const tf2_ros::Buffer & tf_buffer,
  T & output_msg)
{
  output_msg = input_msg;

  // transform to world coordinate
  if (input_msg.header.frame_id != target_frame_id) {
    output_msg.header.frame_id = target_frame_id;
    tf2::Transform tf_target2objects_world;
    {
      const auto ros_target2objects_world = detail::getTransform(
        tf_buffer, input_msg.header.frame_id, target_frame_id, input_msg.header.stamp);
      if (!ros_target2objects_world) {
        return false;
      }
      tf2::fromMsg(*ros_target2objects_world, tf_target2objects_world);
    }
    for (auto & object : output_msg.objects) {
      tf2::Transform tf_objects_world2objects;
      auto & pose_with_cov = object.kinematics.pose_with_covariance;
      tf2::fromMsg(pose_with_cov.pose, tf_objects_world2objects);
      tf2::Transform tf_target2objects = tf_target2objects_world * tf_objects_world2objects;
      // transform pose, frame difference and object pose
      tf2::toMsg(tf_target2objects, pose_with_cov.pose);
      // transform covariance, only the frame difference
      pose_with_cov.covariance =
        tf2::transformCovariance(pose_with_cov.covariance, tf_target2objects_world);
    }
  }
  return true;
}

[[maybe_unused]] inline boost::optional<geometry_msgs::msg::Transform> getTransform(
  const tf2_ros::Buffer & tf_buffer, const std::string & source_frame_id,
  const std::string & target_frame_id, const rclcpp::Time & time)
{
  try {
    geometry_msgs::msg::TransformStamped self_transform_stamped;
    self_transform_stamped = tf_buffer.lookupTransform(
      target_frame_id, source_frame_id, time, rclcpp::Duration::from_seconds(0.5));
    return self_transform_stamped.transform;
  } catch (tf2::TransformException & ex) {
    RCLCPP_WARN_STREAM(rclcpp::get_logger("object_recognition_utils"), ex.what());
    return boost::none;
  }
}

std::optional<TrackedObjects> DecorativeTrackerMergerNode::interpolateObjectState(
  const TrackedObjects::ConstSharedPtr & former_msg,
  const TrackedObjects::ConstSharedPtr & latter_msg, const std_msgs::msg::Header & output_header)
{
  // Assumption: output_header must be newer than former_msg and older than latter_msg
  // There three possible patterns
  // 1. both msg is nullptr
  // 2. former_msg is nullptr
  // 3. latter_msg is nullptr
  // 4. both msg is not nullptr

  // 1. both msg is nullptr
  if (former_msg == nullptr && latter_msg == nullptr) {
    // return null optional
    RCLCPP_DEBUG(this->get_logger(), "interpolation err: both msg is nullptr");
    return std::nullopt;
  }

  // 2. former_msg is nullptr
  if (former_msg == nullptr) {
    // std::cout << "interpolation: 2. former_msg is nullptr" << std::endl;
    // depends on header stamp difference
    if (
      (rclcpp::Time(latter_msg->header.stamp) - rclcpp::Time(output_header.stamp)).seconds() >
      time_sync_threshold_) {
      // do nothing
      RCLCPP_DEBUG(
        this->get_logger(), "interpolation err: latter msg is too different from output msg");
      return std::nullopt;
    } else {  // else, return latter_msg
      return *latter_msg;
    }

    // 3. latter_msg is nullptr
  } else if (latter_msg == nullptr) {
    // std::cout << "interpolation: 3. latter_msg is nullptr" << std::endl;
    // depends on header stamp difference
    const auto dt =
      (rclcpp::Time(output_header.stamp) - rclcpp::Time(former_msg->header.stamp)).seconds();
    if (dt > time_sync_threshold_) {
      // do nothing
      RCLCPP_DEBUG(this->get_logger(), "interpolation err: former msg is too old");
      return std::nullopt;
    } else {
      // else, return former_msg
      return utils::predictPastOrFutureTrackedObjects(*former_msg, output_header);
    }

    // 4. both msg is not nullptr
  } else {
    // do the interpolation
    // std::cout << "interpolation: 4. both msg is not nullptr" << std::endl;
    TrackedObjects interpolated_msg =
      utils::interpolateTrackedObjects(*former_msg, *latter_msg, output_header);
    return interpolated_msg;
  }
}

TrackedObjects predictPastOrFutureTrackedObjects(
  const TrackedObjects & input_objects, const std_msgs::msg::Header & header)
{
  // for each object, predict past or future
  TrackedObjects output_objects;
  output_objects.header = input_objects.header;
  output_objects.header.stamp = header.stamp;

  const auto dt = (rclcpp::Time(header.stamp) - rclcpp::Time(input_objects.header.stamp)).seconds();
  for (const auto & obj : input_objects.objects) {
    output_objects.objects.push_back(predictPastOrFutureTrackedObject(obj, dt));
  }
  return output_objects;
}

TrackedObject predictPastOrFutureTrackedObject(const TrackedObject & obj, const double dt)
{
  // output object
  TrackedObject output;
  // copy input object at first
  output = obj;
  if (dt == 0) {
    return output;
  }

  // get current twist and pose
  const auto twist = obj.kinematics.twist_with_covariance.twist;
  const auto pose = obj.kinematics.pose_with_covariance.pose;

  // get yaw
  const auto yaw = tf2::getYaw(pose.orientation);
  const auto vx = twist.linear.x;
  const auto vy = twist.linear.y;

  // linear prediction equation:
  // x = x0 + vx * cos(yaw) * dt - vy * sin(yaw) * dt
  // y = y0 + vx * sin(yaw) * dt + vy * cos(yaw) * dt
  auto & output_pose = output.kinematics.pose_with_covariance.pose;
  output_pose.position.x += vx * std::cos(yaw) * dt - vy * std::sin(yaw) * dt;
  output_pose.position.y += vx * std::sin(yaw) * dt + vy * std::cos(yaw) * dt;

  // (TODO) covariance prediction

  return output;
}

TrackedObjects interpolateTrackedObjects(
  const TrackedObjects & objects1, const TrackedObjects & objects2, std_msgs::msg::Header header)
{
  // Assumption: time of output header is between objects1 and objects2
  //              time of objects1 < header < objects2

  // define output objects
  TrackedObjects output_objects;
  output_objects.header = header;

  // calc weight
  const auto dt =
    (rclcpp::Time(objects1.header.stamp) - rclcpp::Time(objects2.header.stamp)).seconds();
  const auto dt1 = (rclcpp::Time(objects1.header.stamp) - rclcpp::Time(header.stamp)).seconds();
  const auto weight = dt1 / dt;

  // check if object number is not zero
  if (objects1.objects.size() == 0 && objects2.objects.size() == 0) {
    // if objects1 and objects2 are empty, return empty objects
    return output_objects;
  } else if (objects1.objects.size() == 0) {
    // if objects1 is empty return objects2
    for (const auto & obj2 : objects2.objects) {
      output_objects.objects.push_back(predictPastOrFutureTrackedObject(obj2, dt1 - dt));
    }
    return output_objects;
  } else if (objects2.objects.size() == 0) {
    // if objects2 is empty return objects1
    for (const auto & obj1 : objects1.objects) {
      output_objects.objects.push_back(predictPastOrFutureTrackedObject(obj1, dt1));
    }
  } else {
    // if both objects1 and objects2 are not empty do nothing
  }

  // map to handle selected objects
  std::unordered_map<std::size_t, bool> selected_objects1;
  // iterate with int
  for (std::size_t i = 0; i < objects1.objects.size(); i++) {
    selected_objects1[i] = false;
  }
  // search for objects with int iterator
  for (std::size_t i = 0; i < objects1.objects.size(); i++) {
    for (std::size_t j = 0; j < objects2.objects.size(); j++) {
      if (objects1.objects[i].object_id == objects2.objects[j].object_id) {
        // if id is same, interpolate
        const auto interp_objects =
          linearInterpolationForTrackedObject(objects1.objects[i], objects2.objects[j], weight);
        output_objects.objects.push_back(interp_objects);
        selected_objects1[i] = true;
        break;
      }
    }
    if (selected_objects1[i] == false) {
      // if obj1 is not selected, predict future
      const auto pred_objects = predictPastOrFutureTrackedObject(objects1.objects[i], dt1);
      output_objects.objects.push_back(pred_objects);
    }
  }

  return output_objects;
}

TrackedObject predictPastOrFutureTrackedObject(const TrackedObject & obj, const double dt)
{
  // output object
  TrackedObject output;
  // copy input object at first
  output = obj;
  if (dt == 0) {
    return output;
  }

  // get current twist and pose
  const auto twist = obj.kinematics.twist_with_covariance.twist;
  const auto pose = obj.kinematics.pose_with_covariance.pose;

  // get yaw
  const auto yaw = tf2::getYaw(pose.orientation);
  const auto vx = twist.linear.x;
  const auto vy = twist.linear.y;

  // linear prediction equation:
  // x = x0 + vx * cos(yaw) * dt - vy * sin(yaw) * dt
  // y = y0 + vx * sin(yaw) * dt + vy * cos(yaw) * dt
  auto & output_pose = output.kinematics.pose_with_covariance.pose;
  output_pose.position.x += vx * std::cos(yaw) * dt - vy * std::sin(yaw) * dt;
  output_pose.position.y += vx * std::sin(yaw) * dt + vy * std::cos(yaw) * dt;

  // (TODO) covariance prediction

  return output;
}

TrackedObject linearInterpolationForTrackedObject(
  const TrackedObject & obj1, const TrackedObject & obj2, const double weight)
{
  // interpolate obj1 and obj2 with weight: obj1 * (1 - weight) + obj2 * weight
  // weight = 0: obj1, weight = 1: obj2

  // weight check (0 <= weight <= 1)
  if (weight < 0 || weight > 1) {
    std::cerr << "weight must be 0 <= weight <= 1 in linearInterpolationForTrackedObject function."
              << std::endl;
    return obj1;
  }

  // output object
  TrackedObject output;
  // copy input object at first
  output = obj1;

  // get current twist and pose
  const auto twist1 = obj1.kinematics.twist_with_covariance.twist;
  const auto pose1 = obj1.kinematics.pose_with_covariance.pose;
  const auto twist2 = obj2.kinematics.twist_with_covariance.twist;
  const auto pose2 = obj2.kinematics.pose_with_covariance.pose;

  // interpolate twist
  auto & output_twist = output.kinematics.twist_with_covariance.twist;
  output_twist.linear.x = twist1.linear.x * (1 - weight) + twist2.linear.x * weight;
  output_twist.linear.y = twist1.linear.y * (1 - weight) + twist2.linear.y * weight;
  output_twist.linear.z = twist1.linear.z * (1 - weight) + twist2.linear.z * weight;
  output_twist.angular.x = twist1.angular.x * (1 - weight) + twist2.angular.x * weight;
  output_twist.angular.y = twist1.angular.y * (1 - weight) + twist2.angular.y * weight;
  output_twist.angular.z = twist1.angular.z * (1 - weight) + twist2.angular.z * weight;

  // interpolate pose
  auto & output_pose = output.kinematics.pose_with_covariance.pose;
  output_pose.position.x = pose1.position.x * (1 - weight) + pose2.position.x * weight;
  output_pose.position.y = pose1.position.y * (1 - weight) + pose2.position.y * weight;
  output_pose.position.z = pose1.position.z * (1 - weight) + pose2.position.z * weight;
  // interpolate orientation with slerp
  // https://en.wikipedia.org/wiki/Slerp
  const auto q1 = tf2::Quaternion(
    pose1.orientation.x, pose1.orientation.y, pose1.orientation.z, pose1.orientation.w);
  const auto q2 = tf2::Quaternion(
    pose2.orientation.x, pose2.orientation.y, pose2.orientation.z, pose2.orientation.w);
  const auto q = q1.slerp(q2, weight);
  output_pose.orientation.x = q.x();
  output_pose.orientation.y = q.y();
  output_pose.orientation.z = q.z();
  output_pose.orientation.w = q.w();

  // interpolate shape(mostly for bounding box)
  const auto shape1 = obj1.shape;
  const auto shape2 = obj2.shape;
  if (shape1.type != shape2.type) {
    // if shape type is different, return obj1
  } else {
    if (shape1.type == autoware_perception_msgs::msg::Shape::BOUNDING_BOX) {
      auto & output_shape = output.shape;
      output_shape.dimensions.x = shape1.dimensions.x * (1 - weight) + shape2.dimensions.x * weight;
      output_shape.dimensions.y = shape1.dimensions.y * (1 - weight) + shape2.dimensions.y * weight;
      output_shape.dimensions.z = shape1.dimensions.z * (1 - weight) + shape2.dimensions.z * weight;
    } else if (shape1.type == autoware_perception_msgs::msg::Shape::CYLINDER) {  // NOLINT
      // (TODO) implement and remove NOLINT
    } else if (shape1.type == autoware_perception_msgs::msg::Shape::POLYGON) {  // NOLINT
      // (TODO) implement and remove NOLINT
    } else {
      // when type is unknown, print warning and do nothing
      std::cerr << "unknown shape type in linearInterpolationForTrackedObject function."
                << std::endl;
      return output;
    }
  }

  return output;
}

	Quaternion slerp(const Quaternion& q, const tf2Scalar& t) const
	{
          tf2Scalar theta = angleShortestPath(q) / tf2Scalar(2.0);
		if (theta != tf2Scalar(0.0))
		{
			tf2Scalar d = tf2Scalar(1.0) / tf2Sin(theta);
			tf2Scalar s0 = tf2Sin((tf2Scalar(1.0) - t) * theta);
			tf2Scalar s1 = tf2Sin(t * theta);   
                        if (dot(q) < 0) // Take care of long angle case see http://en.wikipedia.org/wiki/Slerp
                          return Quaternion((m_floats[0] * s0 + -q.x() * s1) * d,
                                              (m_floats[1] * s0 + -q.y() * s1) * d,
                                              (m_floats[2] * s0 + -q.z() * s1) * d,
                                              (m_floats[3] * s0 + -q.m_floats[3] * s1) * d);
                        else
                          return Quaternion((m_floats[0] * s0 + q.x() * s1) * d,
                                              (m_floats[1] * s0 + q.y() * s1) * d,
                                              (m_floats[2] * s0 + q.z() * s1) * d,
                                              (m_floats[3] * s0 + q.m_floats[3] * s1) * d);

		}
		else
		{
			return *this;
		}
	}

bool DecorativeTrackerMergerNode::decorativeMerger(
  const MEASUREMENT_STATE input_sensor, const TrackedObjects::ConstSharedPtr & input_objects_msg)
{
  // get current time
  const auto current_time = rclcpp::Time(input_objects_msg->header.stamp);
  if (inner_tracker_objects_.empty()) {
    for (const auto & object : input_objects_msg->objects) {
      inner_tracker_objects_.push_back(createNewTracker(input_sensor, current_time, object));
    }
  }

  // do prediction for inner objects
  for (auto & object : inner_tracker_objects_) {
    object.predict(current_time);
  }

  // TODO(yoshiri): pre-association

  // associate inner objects and input objects
  /* global nearest neighbor */
  std::unordered_map<int, int> direct_assignment, reverse_assignment;
  const auto & objects1 = input_objects_msg->objects;
  Eigen::MatrixXd score_matrix = calcScoreMatrixForAssociation(
    input_sensor, *input_objects_msg, inner_tracker_objects_, data_association_map_);
  data_association_map_.at("lidar-lidar")
    ->assign(score_matrix, direct_assignment, reverse_assignment);

  // look for tracker
  for (int tracker_idx = 0; tracker_idx < static_cast<int>(inner_tracker_objects_.size());
       ++tracker_idx) {
    auto & object0_state =
      inner_tracker_objects_.at(static_cast<std::vector<int>::size_type>(tracker_idx));
    if (direct_assignment.find(tracker_idx) != direct_assignment.end()) {  // found and merge
      const auto & object1 =
        objects1.at(static_cast<std::vector<int>::size_type>(direct_assignment.at(tracker_idx)));
      // merge object1 into object0_state
      object0_state.updateState(input_sensor, current_time, object1);
    } else {  // not found
      // decrease existence probability
      object0_state.updateWithoutSensor(current_time);
    }
  }
  // look for new object
  for (int object1_idx = 0; object1_idx < static_cast<int>(objects1.size()); ++object1_idx) {
    const auto & object1 = objects1.at(static_cast<std::vector<int>::size_type>(object1_idx));
    if (reverse_assignment.find(object1_idx) != reverse_assignment.end()) {  // found
    } else {                                                                 // not found
      inner_tracker_objects_.push_back(createNewTracker(input_sensor, current_time, object1));
    }
  }
  return true;
}

bool TrackerState::predict(const rclcpp::Time & current_time)
{
  // get dt and give warning if dt is too large
  double dt = (current_time - last_update_time_).seconds();
  if (std::abs(dt) > max_dt_) {
    std::cerr << "[tracking_object_merger] dt is too large: " << dt << std::endl;
    return false;
  }

  // do prediction
  last_update_time_ = current_time;
  return this->predict(dt, utils::predictPastOrFutureTrackedObject);
}

bool TrackerState::predict(
  const double dt, std::function<TrackedObject(const TrackedObject &, double)> func)
{
  const auto predicted_object = func(tracked_object_, dt);
  tracked_object_ = predicted_object;
  return true;
}

Eigen::MatrixXd calcScoreMatrixForAssociation(
  const MEASUREMENT_STATE measurement_state,
  const autoware_perception_msgs::msg::TrackedObjects & objects0,
  const std::vector<TrackerState> & trackers,
  const std::unordered_map<std::string, std::unique_ptr<DataAssociation>> & data_association_map
  // const bool debug_log, const std::string & file_name // do not logging for now
)
{
  // get current time
  const rclcpp::Time current_time = rclcpp::Time(objects0.header.stamp);

  // calc score matrix
  Eigen::MatrixXd score_matrix = Eigen::MatrixXd::Zero(
    static_cast<Eigen::Index>(trackers.size()), static_cast<Eigen::Index>(objects0.objects.size()));
  for (size_t trackers_idx = 0; trackers_idx < trackers.size(); ++trackers_idx) {
    const auto & tracker_obj = trackers.at(trackers_idx);
    const auto & object1 = tracker_obj.getObject();
    const auto & tracker_state = tracker_obj.getCurrentMeasurementState(current_time);

    for (size_t objects0_idx = 0; objects0_idx < objects0.objects.size(); ++objects0_idx) {
      const auto & object0 = objects0.objects.at(objects0_idx);
      // switch calc score function by input and trackers measurement state
      // we assume that lidar and radar are exclusive
      double score;
      const auto input_has_lidar = measurement_state & MEASUREMENT_STATE::LIDAR;
      const auto tracker_has_lidar = tracker_state & MEASUREMENT_STATE::LIDAR;
      if (input_has_lidar && tracker_has_lidar) {
        score = data_association_map.at("lidar-lidar")->calcScoreBetweenObjects(object0, object1);
      } else if (!input_has_lidar && !tracker_has_lidar) {
        score = data_association_map.at("radar-radar")->calcScoreBetweenObjects(object0, object1);
      } else {
        score = data_association_map.at("lidar-radar")->calcScoreBetweenObjects(object0, object1);
      }
      score_matrix(
        static_cast<Eigen::Index>(trackers_idx), static_cast<Eigen::Index>(objects0_idx)) = score;
    }
  }
  return score_matrix;
}

MEASUREMENT_STATE TrackerState::getCurrentMeasurementState(const rclcpp::Time & current_time) const
{
  MEASUREMENT_STATE measurement_state = MEASUREMENT_STATE::NONE;
  // check LIDAR
  if (last_updated_time_map_.find(MEASUREMENT_STATE::LIDAR) != last_updated_time_map_.end()) {
    if ((current_time - last_updated_time_map_.at(MEASUREMENT_STATE::LIDAR)).seconds() < max_dt_) {
      measurement_state = measurement_state | MEASUREMENT_STATE::LIDAR;
    }
  }
  // check RADAR
  if (last_updated_time_map_.find(MEASUREMENT_STATE::RADAR) != last_updated_time_map_.end()) {
    if ((current_time - last_updated_time_map_.at(MEASUREMENT_STATE::RADAR)).seconds() < max_dt_) {
      measurement_state = measurement_state | MEASUREMENT_STATE::RADAR;
    }
  }
  // check CAMERA
  if (last_updated_time_map_.find(MEASUREMENT_STATE::CAMERA) != last_updated_time_map_.end()) {
    if ((current_time - last_updated_time_map_.at(MEASUREMENT_STATE::CAMERA)).seconds() < max_dt_) {
      measurement_state = measurement_state | MEASUREMENT_STATE::CAMERA;
    }
  }
  return measurement_state;
}

double DataAssociation::calcScoreBetweenObjects(
  const autoware_perception_msgs::msg::TrackedObject & object0,
  const autoware_perception_msgs::msg::TrackedObject & object1) const
{
  const std::uint8_t object1_label =
    autoware::object_recognition_utils::getHighestProbLabel(object1.classification);
  const std::uint8_t object0_label =
    autoware::object_recognition_utils::getHighestProbLabel(object0.classification);

  double score = 0.0;
  if (can_assign_matrix_(object1_label, object0_label)) {
    const double max_dist = max_dist_matrix_(object1_label, object0_label);
    const double dist = autoware_utils_geometry::calc_distance2d(
      object0.kinematics.pose_with_covariance.pose.position,
      object1.kinematics.pose_with_covariance.pose.position);

    bool passed_gate = true;
    // dist gate
    {  // passed_gate is always true
      if (max_dist < dist) passed_gate = false;
    }
    // angle gate
    if (passed_gate) {
      const double max_rad = max_rad_matrix_(object1_label, object0_label);
      const double angle = getFormedYawAngle(
        object0.kinematics.pose_with_covariance.pose.orientation,
        object1.kinematics.pose_with_covariance.pose.orientation, false);
      if (std::fabs(max_rad) < M_PI && std::fabs(max_rad) < std::fabs(angle)) passed_gate = false;
    }
    // 2d iou gate
    if (passed_gate) {
      const double min_iou = min_iou_matrix_(object1_label, object0_label);
      const double min_union_iou_area = 1e-2;
      const double iou =
        autoware::object_recognition_utils::get2dIoU(object0, object1, min_union_iou_area);
      if (iou < min_iou) passed_gate = false;
    }
    // max velocity diff gate
    if (passed_gate) {
      const double max_velocity_diff = max_velocity_diff_matrix_(object1_label, object0_label);
      // calc absolute velocity diff (only thinking about speed)
      const auto speed0 = std::hypot(
        object0.kinematics.twist_with_covariance.twist.linear.x,
        object0.kinematics.twist_with_covariance.twist.linear.y);
      const auto speed1 = std::hypot(
        object1.kinematics.twist_with_covariance.twist.linear.x,
        object1.kinematics.twist_with_covariance.twist.linear.y);
      const double velocity_diff = std::fabs(speed0 - speed1);
      if (max_velocity_diff < velocity_diff) passed_gate = false;
    }

    // all gate is passed
    if (passed_gate) {
      score = (max_dist - std::min(dist, max_dist)) / max_dist;
      if (score < score_threshold_) score = 0.0;
    }
  }
  return score;
}

inline std::uint8_t getHighestProbLabel(
  const std::vector<ObjectClassification> & object_classifications)
{
  return getHighestProbClassification(object_classifications).label;
}

inline ObjectClassification getHighestProbClassification(
  const std::vector<ObjectClassification> & object_classifications)
{
  if (object_classifications.empty()) {
    return ObjectClassification{};
  }
  return *std::max_element(
    std::begin(object_classifications), std::end(object_classifications),
    [](const auto & a, const auto & b) { return a.probability < b.probability; });
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double getFormedYawAngle(
  const geometry_msgs::msg::Quaternion & quat0, const geometry_msgs::msg::Quaternion & quat1,
  const bool distinguish_front_or_back = true)
{
  const double yaw0 = autoware_utils_math::normalize_radian(tf2::getYaw(quat0));
  const double yaw1 = autoware_utils_math::normalize_radian(tf2::getYaw(quat1));
  const double angle_range = distinguish_front_or_back ? M_PI : M_PI_2;
  const double angle_step = distinguish_front_or_back ? 2.0 * M_PI : M_PI;
  // Fixed yaw0 to be in the range of +-90 or 180 degrees of yaw1
  double fixed_yaw0 = yaw0;
  while (angle_range <= yaw1 - fixed_yaw0) {
    fixed_yaw0 = fixed_yaw0 + angle_step;
  }
  while (angle_range <= fixed_yaw0 - yaw1) {
    fixed_yaw0 = fixed_yaw0 - angle_step;
  }
  return std::fabs(fixed_yaw0 - yaw1);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

double get2dIoU(
  const T1 & source_object, const T2 & target_object, const double min_union_area = 0.01)
{
  const auto source_polygon = autoware_utils_geometry::to_polygon2d(source_object);
  if (boost::geometry::area(source_polygon) < MIN_AREA) return 0.0;
  const auto target_polygon = autoware_utils_geometry::to_polygon2d(target_object);
  if (boost::geometry::area(target_polygon) < MIN_AREA) return 0.0;

  const double intersection_area = getIntersectionArea(source_polygon, target_polygon);
  if (intersection_area < MIN_AREA) return 0.0;
  const double union_area = getUnionArea(source_polygon, target_polygon);

  const double iou =
    union_area < min_union_area ? 0.0 : std::min(1.0, intersection_area / union_area);
  return iou;
}

Polygon2d to_polygon2d(
  const geometry_msgs::msg::Pose & pose, const autoware_perception_msgs::msg::Shape & shape)
{
  Polygon2d polygon;

  if (shape.type == autoware_perception_msgs::msg::Shape::BOUNDING_BOX) {
    const auto point0 = autoware_utils_geometry::calc_offset_pose(
                          pose, shape.dimensions.x / 2.0, shape.dimensions.y / 2.0, 0.0)
                          .position;
    const auto point1 = autoware_utils_geometry::calc_offset_pose(
                          pose, -shape.dimensions.x / 2.0, shape.dimensions.y / 2.0, 0.0)
                          .position;
    const auto point2 = autoware_utils_geometry::calc_offset_pose(
                          pose, -shape.dimensions.x / 2.0, -shape.dimensions.y / 2.0, 0.0)
                          .position;
    const auto point3 = autoware_utils_geometry::calc_offset_pose(
                          pose, shape.dimensions.x / 2.0, -shape.dimensions.y / 2.0, 0.0)
                          .position;

    append_point_to_polygon(polygon, point0);
    append_point_to_polygon(polygon, point1);
    append_point_to_polygon(polygon, point2);
    append_point_to_polygon(polygon, point3);
  } else if (shape.type == autoware_perception_msgs::msg::Shape::CYLINDER) {
    const double radius = shape.dimensions.x / 2.0;
    constexpr int circle_discrete_num = 6;
    for (int i = 0; i < circle_discrete_num; ++i) {
      geometry_msgs::msg::Point point;
      point.x = std::cos(
                  (static_cast<double>(i) / static_cast<double>(circle_discrete_num)) * 2.0 * M_PI +
                  M_PI / static_cast<double>(circle_discrete_num)) *
                  radius +
                pose.position.x;
      point.y = std::sin(
                  (static_cast<double>(i) / static_cast<double>(circle_discrete_num)) * 2.0 * M_PI +
                  M_PI / static_cast<double>(circle_discrete_num)) *
                  radius +
                pose.position.y;
      append_point_to_polygon(polygon, point);
    }
  } else if (shape.type == autoware_perception_msgs::msg::Shape::POLYGON) {
    const double poly_yaw = tf2::getYaw(pose.orientation);
    const auto rotated_footprint = rotate_polygon(shape.footprint, poly_yaw);
    for (const auto rel_point : rotated_footprint.points) {
      geometry_msgs::msg::Point abs_point;
      abs_point.x = pose.position.x + rel_point.x;
      abs_point.y = pose.position.y + rel_point.y;

      append_point_to_polygon(polygon, abs_point);
    }
  } else {
    throw std::logic_error("The shape type is not supported in autoware_utils.");
  }

  // NOTE: push back the first point in order to close polygon
  if (!polygon.outer().empty()) {
    append_point_to_polygon(polygon, polygon.outer().front());
  }

  return is_clockwise(polygon) ? polygon : inverse_clockwise(polygon);
}

  using autoware_utils_geometry::calc_offset_pose;
  Polygon2d polygon;
  const auto point0 = calc_offset_pose(base_link_pose, base_to_front, width / 2.0, 0.0).position;
  const auto point1 = calc_offset_pose(base_link_pose, base_to_front, -width / 2.0, 0.0).position;
  const auto point2 = calc_offset_pose(base_link_pose, -base_to_rear, -width / 2.0, 0.0).position;
  const auto point3 = calc_offset_pose(base_link_pose, -base_to_rear, width / 2.0, 0.0).position;

  append_point_to_polygon(polygon, point0);
  append_point_to_polygon(polygon, point1);
  append_point_to_polygon(polygon, point2);
  append_point_to_polygon(polygon, point3);
  append_point_to_polygon(polygon, point0);

  return is_clockwise(polygon) ? polygon : inverse_clockwise(polygon);
}

double get_area(const autoware_perception_msgs::msg::Shape & shape)
{
  if (shape.type == autoware_perception_msgs::msg::Shape::BOUNDING_BOX) {
    return get_rectangle_area(shape.dimensions);
  } else if (shape.type == autoware_perception_msgs::msg::Shape::CYLINDER) {
    return get_circle_area(shape.dimensions);
  } else if (shape.type == autoware_perception_msgs::msg::Shape::POLYGON) {
    return get_polygon_area(shape.footprint);
  }

  throw std::logic_error("The shape type is not supported in autoware_utils.");
}

geometry_msgs::msg::Polygon rotate_polygon(
  const geometry_msgs::msg::Polygon & polygon, const double & angle)
{
  const double cos = std::cos(angle);
  const double sin = std::sin(angle);
  geometry_msgs::msg::Polygon rotated_polygon;
  for (const auto & point : polygon.points) {
    auto rotated_point = point;
    rotated_point.x = cos * point.x - sin * point.y;
    rotated_point.y = sin * point.x + cos * point.y;
    rotated_polygon.points.push_back(rotated_point);
  }
  return rotated_polygon;
}

void append_point_to_polygon(Polygon2d & polygon, const geometry_msgs::msg::Point & geom_point)
{
  Point2d point;
  point.x() = geom_point.x;
  point.y() = geom_point.y;

  bg::append(polygon.outer(), point);
}

bool is_clockwise(const Polygon2d & polygon)
{
  const int n = polygon.outer().size();
  const double x_offset = polygon.outer().at(0).x();
  const double y_offset = polygon.outer().at(0).y();
  double sum = 0.0;
  for (std::size_t i = 0; i < polygon.outer().size(); ++i) {
    sum +=
      (polygon.outer().at(i).x() - x_offset) * (polygon.outer().at((i + 1) % n).y() - y_offset) -
      (polygon.outer().at(i).y() - y_offset) * (polygon.outer().at((i + 1) % n).x() - x_offset);
  }

  return sum < 0.0;
}

Polygon2d inverse_clockwise(const Polygon2d & polygon)
{
  auto output_polygon = polygon;
  boost::geometry::reverse(output_polygon);
  return output_polygon;
}

inline double getIntersectionArea(
  const Polygon2d & source_polygon, const Polygon2d & target_polygon)
{
  std::vector<Polygon2d> intersection_polygons;
  boost::geometry::intersection(source_polygon, target_polygon, intersection_polygons);
  return getSumArea(intersection_polygons);
}

inline double getSumArea(const std::vector<Polygon2d> & polygons)
{
  return std::accumulate(
    polygons.begin(), polygons.end(), 0.0,
    [](double acc, const Polygon2d & p) { return acc + boost::geometry::area(p); });
}

inline double getUnionArea(const Polygon2d & source_polygon, const Polygon2d & target_polygon)
{
  std::vector<Polygon2d> union_polygons;
  boost::geometry::union_(source_polygon, target_polygon, union_polygons);
  return getSumArea(union_polygons);
}

inline double getSumArea(const std::vector<Polygon2d> & polygons)
{
  return std::accumulate(
    polygons.begin(), polygons.end(), 0.0,
    [](double acc, const Polygon2d & p) { return acc + boost::geometry::area(p); });
}

void DataAssociation::assign(
  const Eigen::MatrixXd & src, std::unordered_map<int, int> & direct_assignment,
  std::unordered_map<int, int> & reverse_assignment)
{
  std::vector<std::vector<double>> score(static_cast<size_t>(src.rows()));
  for (int row = 0; row < src.rows(); ++row) {
    score.at(static_cast<size_t>(row)).resize(static_cast<size_t>(src.cols()));
    for (int col = 0; col < src.cols(); ++col) {
      score.at(static_cast<size_t>(row)).at(static_cast<size_t>(col)) = src(row, col);
    }
  }
  // Solve
  gnn_solver_ptr_->maximizeLinearAssignment(score, &direct_assignment, &reverse_assignment);

  for (auto itr = direct_assignment.begin(); itr != direct_assignment.end();) {
    if (src(itr->first, itr->second) < score_threshold_) {
      itr = direct_assignment.erase(itr);
      continue;
    } else {
      ++itr;
    }
  }
  for (auto itr = reverse_assignment.begin(); itr != reverse_assignment.end();) {
    if (src(itr->second, itr->first) < score_threshold_) {
      itr = reverse_assignment.erase(itr);
      continue;
    } else {
      ++itr;
    }
  }
}

void MuSSP::maximizeLinearAssignment(
  const std::vector<std::vector<double>> & cost, std::unordered_map<int, int> * direct_assignment,
  std::unordered_map<int, int> * reverse_assignment)
{
  // Terminate if the graph is empty
  if (cost.size() == 0 || cost.at(0).size() == 0) {
    return;
  }

  // Solve DA by muSSP
  solve_muSSP(cost, direct_assignment, reverse_assignment);
}

int solve_muSSP(
  const std::vector<std::vector<double>> & cost, std::unordered_map<int, int> * direct_assignment,
  std::unordered_map<int, int> * reverse_assignment)
{
  // For debug
  const bool verbose = false;
  // const bool verbose = true;

  //// reading data
  clock_t t_start = clock();

  // std::string inFileName = (argc > 1) ? argv[1] : "/home/congchao/Desktop/dev/muSSP/input_117982_193870.txt";
  // std::unique_ptr<Graph> org_graph = std::unique_ptr<Graph>(init(inFileName));
  std::unique_ptr<Graph> org_graph = std::unique_ptr<Graph>(init_from_cost_mat(cost));
  clock_t t_end = clock();
  long double parsing_time = t_end - t_start;

  std::array<long double, 10> duration;
  duration.fill(0);
  //// 1: remove dummy edges
  t_start = clock();
  org_graph->invalid_edge_rm();
  t_end = clock();
  duration[0] += t_end - t_start;

  ////save path and path cost
  std::vector<double> path_cost;
  std::vector<std::vector<int>> path_set;
  int path_num = 0;
  t_start = clock();
  //// 2: initialize shortest path tree from the DAG
  org_graph->shortest_path_dag();
  t_end = clock();
  duration[1] += t_end - t_start;

  path_cost.push_back(org_graph->distance2src[org_graph->sink_id_]);
  org_graph->cur_path_max_cost =
    -org_graph->distance2src[org_graph->sink_id_];  // the largest cost we can accept

  //// 3: convert edge cost (make all weights positive)
  t_start = clock();
  org_graph->update_allgraph_weights();
  t_end = clock();
  duration[2] += t_end - t_start;

  //// 8: extract shortest path
  t_start = clock();
  org_graph->extract_shortest_path();
  t_end = clock();
  duration[7] += t_end - t_start;

  path_set.push_back(org_graph->shortest_path);
  path_num++;

  std::vector<unsigned long> update_node_num;

  //// 4: find nodes for updating based on branch node
  std::vector<int> node_id4updating;
  t_start = clock();
  org_graph->find_node_set4update(node_id4updating);
  t_end = clock();
  duration[3] += t_end - t_start;

  //// 10: rebuild residual graph by flipping paths
  t_start = clock();
  org_graph->flip_path();  //also erase the top sinker
  t_end = clock();
  duration[9] += t_end - t_start;
  while (true) {
    //// 6: update shortest path tree based on the selected sub-graph
    t_start = clock();
    org_graph->update_shortest_path_tree_recursive(node_id4updating);
    if (verbose) {
      printf("Iteration #%d, updated node number  %ld \n", path_num, org_graph->upt_node_num);
    }
    t_end = clock();
    duration[5] += t_end - t_start;

    //// 7: update sink node (heap)
    t_start = clock();
    org_graph->update_sink_info(node_id4updating);
    t_end = clock();
    duration[6] += t_end - t_start;

    update_node_num.push_back(node_id4updating.size());

    //// 8: extract shortest path
    t_start = clock();
    org_graph->extract_shortest_path();
    t_end = clock();
    duration[7] += t_end - t_start;

    // test if stop
    double cur_path_cost = path_cost[path_num - 1] + org_graph->distance2src[org_graph->sink_id_];

    if (cur_path_cost > -0.0000001) {
      break;
    }

    path_cost.push_back(cur_path_cost);
    org_graph->cur_path_max_cost = -cur_path_cost;
    path_set.push_back(org_graph->shortest_path);
    path_num++;

    //// 9: update weights
    t_start = clock();
    org_graph->update_subgraph_weights(node_id4updating);
    t_end = clock();
    duration[8] += t_end - t_start;

    //// 4: find nodes for updating
    t_start = clock();
    org_graph->find_node_set4update(node_id4updating);
    t_end = clock();
    duration[3] += t_end - t_start;
    //// 10: rebuild the graph
    t_start = clock();
    org_graph->flip_path();
    t_end = clock();
    duration[9] += t_end - t_start;
  }

  //// out put results and time consuming
  if (verbose) {
    std::cout << "Parsing time is: " << parsing_time / CLOCKS_PER_SEC << " s" << std::endl;
  }

  long double all_cpu_time = 0;
  for (int i = 0; i < 10; i++) {
    auto time_elapsed_ms = 1000.0 * duration[i] / CLOCKS_PER_SEC;
    all_cpu_time += time_elapsed_ms;
    if (verbose) {
      std::cout << "the " << i + 1 << " step used: " << time_elapsed_ms / 1000.0 << " s\n";
    }
  }
  if (verbose) {
    std::cout << "The overall time is " << all_cpu_time / 1000.0 << " s\n\n";
  }

  //// start validation
  if (false) {
    double cost_sum = 0, cost_sum_recalculate = 0;
    for (auto && i : path_cost) {
      cost_sum += i;
    }
    for (auto && tmpPath : path_set) {
      double tmp_path_cost = 0;
      for (size_t j = 0; j < tmpPath.size() - 1; j++) {
        int tmp_edge_id = org_graph->node_id2edge_id[Graph::node_key(tmpPath[j + 1], tmpPath[j])];
        tmp_path_cost += org_graph->edge_org_weights[tmp_edge_id];
        org_graph->edge_org_weights[tmp_edge_id] *= -1;
      }
      cost_sum_recalculate += tmp_path_cost;
    }
    unsigned long total_upt_node_num = 0;
    for (auto && i : update_node_num) {
      total_upt_node_num += i;
    }

    if (verbose) {
      printf(
        "The number of paths: %ld, total cost is %.7f, real-cost %.7f, final cost is: %.7f.\n",
        path_cost.size(), cost_sum, cost_sum_recalculate, path_cost[path_cost.size() - 1]);
    }
  }
  double cost_sum = 0;
  for (auto && i : path_cost) {
    cost_sum += i;
  }
  if (verbose) {
    printf(
      "The number of paths: %ld, total cost is %.7f, final path cost is: %.7f.\n", path_cost.size(),
      cost_sum, path_cost[path_cost.size() - 1]);
  }

  //   /*********write detailed flow to txt********/
  // if (argc > 3) {
  //     print_solution(org_graph.get(), path_set, "output.txt");//"output_edge_rm.txt"
  // }
  if (verbose) {
    for (auto path : path_set) {
      for (auto node : path) {
        std::cout << node + 1 << "->";
      }
      std::cout << std::endl;
    }
  }

  // Get assignments
  convert_flow_to_assignment(
    org_graph.get(), path_set, cost.size(), cost.at(0).size(), direct_assignment,
    reverse_assignment);

  return 0;
}

Graph * init_from_cost_mat(const std::vector<std::vector<double>> & cost)
{
  // Weight value of dummy arcs
  const double INF_WEIGHT = 100;

  int n_rows, n_cols;
  n_rows = cost.size();
  n_cols = cost.at(0).size();
  assert(n_rows > 0 && n_cols > 0);

  // Num of nodes
  int n = (n_rows + n_cols + 1) * 2;
  // Num of edges
  int m = n_rows * n_cols + (n_rows + n_cols) * 3;
  // Reduce num of edges by removed edges
  for (int i = 1; i <= n_rows; i++) {
    for (int j = 1; j <= n_cols; j++) {
      if (cost.at(i - 1).at(j - 1) == 0) {
        m--;
      }
    }
  }

  double en_weight = 0;
  double ex_weight = 0;

  auto * resG = new Graph(n, m, 0, n - 1, en_weight, ex_weight);
  int edge_id = 0;

  // Helper function to add an edge
  auto add_edge_wrapper = [&](int tail, int head, double weight) {
    resG->add_edge(tail - 1, head - 1, edge_id++, weight);
  };

  // Add arcs
  //// source (1) -> o_i
  for (int i = 1; i <= n_rows; i++) {
    add_edge_wrapper(1, i * 2, 0);
  }
  for (int j = 1; j <= n_cols; j++) {
    add_edge_wrapper(1, (j + n_rows) * 2, INF_WEIGHT);
  }

  // h_i -> sink (n_nodes)
  for (int i = 1; i <= n_rows; i++) {
    add_edge_wrapper(i * 2 + 1, n, INF_WEIGHT);
  }
  for (int j = 1; j <= n_cols; j++) {
    add_edge_wrapper((j + n_rows) * 2 + 1, n, 0);
  }

  // o_i -> h_i
  for (int i = 1; i <= n_rows; i++) {
    add_edge_wrapper(i * 2, i * 2 + 1, 0);
  }
  for (int j = 1; j <= n_cols; j++) {
    add_edge_wrapper((j + n_rows) * 2, (j + n_rows) * 2 + 1, 0);
  }

  // h_i -> o_j
  for (int i = 1; i <= n_rows; i++) {
    for (int j = 1; j <= n_cols; j++) {
      if (cost.at(i - 1).at(j - 1) > 0) {
        add_edge_wrapper(i * 2 + 1, (j + n_rows) * 2, -cost.at(i - 1).at(j - 1));
      }
    }
  }

  return resG;
}

void Graph::add_edge(int tail_id, int head_id, int edge_id, double weight) {

    V_[tail_id].add_successor(head_id, edge_id, weight);
    V_[head_id].add_precursor(tail_id, edge_id, weight);

    // To format results into direct/reverse assignment
    node_id2edge_id.insert({node_key(head_id, tail_id), edge_id});
    node_id2edge_id.insert({node_key(tail_id, head_id), edge_id});
    edge_tail_head.emplace_back(std::make_pair(tail_id, head_id));

    if (false) {
        /******
         * for results validation only, no need to use in real application
         * ********/
        edge_weights.push_back(weight);
        //// there will be no collisions for insertion, so complexity is O(1)
        node_id2edge_id.insert({node_key(head_id, tail_id), edge_id});
        node_id2edge_id.insert({node_key(tail_id, head_id), edge_id});

        //// for results validation
        edge_tail_head.emplace_back(std::make_pair(tail_id, head_id));
        edge_org_weights.push_back(weight);

        if (static_cast<int>(edge_weights.size()) - 1 != edge_id)
            std::cout << "we got wrong edge number" << std::endl;
    }
}

