void Graph::shortest_path_dag() {
    std::stack<int> Stack;
    // Mark all the vertices as not visited
    std::vector<bool> visited(num_nodes_, false);

    //// Call the recursive helper function to store Topological Sort starting from all vertices one by one
    for (int i = 0; i < this->num_nodes_; i++)
        if (!visited[i])
            topologicalSortUtil(i, visited, Stack);

    // Initialize distances to all vertices as infinite and distance to source as 0
    for (int i = 1; i<num_nodes_; i+=2)
        distance2src[i] = V_[i].precursor_edges_weights[0];
    for (int i = 2; i<num_nodes_; i+=2)
        distance2src[i] = MUSSP_FINF;

    distance2src[src_id_] = 0;
    ancestor_node_id[src_id_] = 0;
    parent_node_id[src_id_] = 0;
    // Process vertices in topological order
    Stack.pop(); // pop up the source, because every node has been set as en_weight_
    while (!Stack.empty()) {
        // Get the next vertex from topological order
        int cur_node_id = Stack.top();
        Stack.pop();

        ancestor_node_id[cur_node_id] = src_id_ == parent_node_id[cur_node_id] ?
                                        cur_node_id : ancestor_node_id[parent_node_id[cur_node_id]];

        if (cur_node_id != sink_id_)
            ancestors_descendants[ancestor_node_id[cur_node_id]].push_back(cur_node_id);

        // Update distances of all adjacent vertices
        for (size_t i = 0; i < V_[cur_node_id].successor_idx.size(); ++i) {
            int cur_succ_id = V_[cur_node_id].successor_idx[i];
            double cur_distance = distance2src[cur_node_id] + V_[cur_node_id].successor_edges_weights[i];
            if (distance2src[cur_succ_id] - cur_distance > 0.0000001)
            {
                distance2src[cur_succ_id] = cur_distance;
                parent_node_id[cur_succ_id] = cur_node_id;
            }
        }
    }

    //// update price
    for (int i = 0; i < this->num_nodes_; i++){
        V_[i].price -= distance2src[i];
    }
}

void Graph::topologicalSortUtil(int v, std::vector<bool>& visited, std::stack<int> &Stack) {
    // Mark the current node as visited
    visited[v] = true;

    // Recur for all the vertices adjacent to this vertex
    for (auto node_id : V_[v].successor_idx)//(int i = 0; i < this->V_[v].successor_idx.size(); ++i)
    {
        if (!visited[node_id])
            topologicalSortUtil(node_id, visited, Stack);
    }
    // Push current vertex to stack which stores topological sort
    Stack.push(v);
}

void Graph::extract_shortest_path() {
    shortest_path.clear();
    int tmp_node_id = sink_id_;
    while (tmp_node_id != src_id_) {
        shortest_path.push_back(tmp_node_id);
        tmp_node_id = parent_node_id[tmp_node_id];
    }
    shortest_path.push_back(src_id_);
}

void Graph::flip_path() { // erase the best one link to sink
    /** for 2 and end-1, specially handled ***/
        // node path(2)
        int node_tmp = shortest_path[shortest_path.size() - 2];// the path currently is from sink to src
        std::vector<int>::iterator edge_id_it;
        std::vector<double>::iterator edge_weight_it;
        double tmp_edge_weight;
        auto it = find(V_[node_tmp].successor_idx.begin(), V_[node_tmp].successor_idx.end(),
                       shortest_path[shortest_path.size() - 3]);
        //// erase
        auto pos = it - V_[node_tmp].successor_idx.begin();
        //V_[node_tmp].successor_edges_idx.erase(V_[node_tmp].successor_edges_idx.begin() + pos);
        tmp_edge_weight = *(V_[node_tmp].successor_edges_weights.begin() + pos);
        V_[node_tmp].successor_edges_weights.erase(V_[node_tmp].successor_edges_weights.begin() + pos);
        V_[node_tmp].successor_idx.erase(it);

        //// add
        it = find(V_[node_tmp].precursor_idx.begin(), V_[node_tmp].precursor_idx.end(), src_id_);
        *it = shortest_path[shortest_path.size() - 3];
        parent_node_id[node_tmp] = *it;
        pos = it - V_[node_tmp].precursor_idx.begin();
        //edge_id_it = V_[node_tmp].precursor_edges_idx.begin() + pos;
        //*edge_id_it = node_id2edge_id[node_key(node_tmp, *it)];
        edge_weight_it = V_[node_tmp].precursor_edges_weights.begin() + pos;
        *edge_weight_it = -tmp_edge_weight;

        //// node path(end-1)
        node_tmp = shortest_path[1];
        it = find(V_[node_tmp].precursor_idx.begin(), V_[node_tmp].precursor_idx.end(), shortest_path[2]);
        pos = it - V_[node_tmp].precursor_idx.begin();
        //// erase
        tmp_edge_weight = *(V_[node_tmp].precursor_edges_weights.begin() + pos);
        V_[node_tmp].precursor_edges_weights.erase(V_[node_tmp].precursor_edges_weights.begin() + pos);

        //V_[node_tmp].precursor_edges_idx.erase(V_[node_tmp].precursor_edges_idx.begin() + pos);
        V_[node_tmp].precursor_idx.erase(it);
        parent_node_id[node_tmp] = -1;
        //// add
        it = find(V_[node_tmp].successor_idx.begin(), V_[node_tmp].successor_idx.end(), sink_id_);
        *it = shortest_path[2];
        pos = it - V_[node_tmp].successor_idx.begin();
        //edge_id_it = V_[node_tmp].successor_edges_idx.begin() + pos;
        //*edge_id_it = node_id2edge_id[node_key(*it, node_tmp)];
        edge_weight_it = V_[node_tmp].successor_edges_weights.begin() + pos;
        *edge_weight_it = -tmp_edge_weight;

        // from 3 to end - 2, reverse their precursor
        for (unsigned long i = shortest_path.size() - 3; i >= 2; i--) {
            node_tmp = shortest_path[i];
            it = find(V_[node_tmp].precursor_idx.begin(), V_[node_tmp].precursor_idx.end(), shortest_path[i + 1]);
            *it = shortest_path[i - 1];
            parent_node_id[node_tmp] = *it;
            pos = it - V_[node_tmp].precursor_idx.begin();

            edge_weight_it = V_[node_tmp].precursor_edges_weights.begin() + pos;
            tmp_edge_weight = *edge_weight_it;

            it = find(V_[node_tmp].successor_idx.begin(), V_[node_tmp].successor_idx.end(), shortest_path[i - 1]);
            *it = shortest_path[i + 1];
            pos = it - V_[node_tmp].successor_idx.begin();

            *edge_weight_it = -*(V_[node_tmp].successor_edges_weights.begin() + pos);
            *(V_[node_tmp].successor_edges_weights.begin() + pos) = -tmp_edge_weight;

        }

    //// after flipping, there is a node that no longer can access sink from itself
    sink_info->sink_precursor_weights[sink_info->sink_precursors.begin()->second] = MUSSP_FINF;
    sink_info->sink_precursors.erase(sink_info->sink_precursors.begin());
}

void convert_flow_to_assignment(
  Graph * resG, std::vector<std::vector<int>> path_set, int n_rows, int n_cols,
  std::unordered_map<int, int> * direct_assignment,
  std::unordered_map<int, int> * reverse_assignment)
{
  (void)n_cols;

  std::vector<bool> edge_visited_flag(resG->num_edges_);

  // Helper function to check if the edge is a bridge (i.e., h_i -> o_j)
  auto is_bridge = [&](int a, int b) {
    return (a > resG->src_id_ && a <= n_rows * 2 && a % 2 == 0) &&
           (b > n_rows * 2 && b < resG->sink_id_ && b % 2 == 1);
  };

  // Compute flow values of edges
  for (size_t i = 0; i < path_set.size(); i++) {
    for (size_t j = 0; j < path_set[i].size() - 1; j++) {
      int tail = path_set[i][j];
      int head = path_set[i][j + 1];

      int edge_idx = resG->node_id2edge_id[Graph::node_key(tail, head)];
      edge_visited_flag[edge_idx] = !edge_visited_flag[edge_idx];
    }
  }

  // Get assignments
  for (int i = 0; i < resG->num_edges_; i++) {
    if (edge_visited_flag[i]) {
      int tail = resG->edge_tail_head[i].first;
      int head = resG->edge_tail_head[i].second;
      assert(tail < head);

      if (is_bridge(tail, head)) {
        int i_row = tail / 2 - 1;
        int i_col = (head + 1) / 2 - n_rows - 1;
        assert(i_row >= 0 && i_row <= n_rows - 1);
        assert(i_col >= 0 && i_col <= n_cols - 1);

        (*direct_assignment)[i_row] = i_col;
        (*reverse_assignment)[i_col] = i_row;
      }
    }
  }
}

static inline size_t node_key(int i,int j)
{
    return (size_t) i << 32 | (unsigned int) j;
}

bool TrackerState::updateState(
  const MEASUREMENT_STATE input, const rclcpp::Time & current_time,
  const TrackedObject & tracked_object)
{
  // calc dt
  double dt = (current_time - last_update_time_).seconds();
  if (dt < 0.0) {
    std::cerr << "[tracking_object_merger] dt is negative: " << dt << std::endl;
    return false;
  }

  // predict
  if (dt > 0.0) {
    this->predict(dt, utils::predictPastOrFutureTrackedObject);
  }

  // get current measurement state
  measurement_state_ = getCurrentMeasurementState(current_time);

  // update with input
  if (input & MEASUREMENT_STATE::LIDAR) {
    updateWithLIDAR(current_time, tracked_object);
  }
  if (input & MEASUREMENT_STATE::RADAR) {
    updateWithRADAR(current_time, tracked_object);
  }
  if (input & MEASUREMENT_STATE::CAMERA) {
    updateWithCAMERA(current_time, tracked_object);
  }
  return true;
}

MEASUREMENT_STATE TrackerState::getCurrentMeasurementState(const rclcpp::Time & current_time) const
{
  MEASUREMENT_STATE measurement_state = MEASUREMENT_STATE::NONE;
  // check LIDAR
  if (last_updated_time_map_.find(MEASUREMENT_STATE::LIDAR) != last_updated_time_map_.end()) {
    if ((current_time - last_updated_time_map_.at(MEASUREMENT_STATE::LIDAR)).seconds() < max_dt_) {
      measurement_state = measurement_state | MEASUREMENT_STATE::LIDAR;
    }
  }
  // check RADAR
  if (last_updated_time_map_.find(MEASUREMENT_STATE::RADAR) != last_updated_time_map_.end()) {
    if ((current_time - last_updated_time_map_.at(MEASUREMENT_STATE::RADAR)).seconds() < max_dt_) {
      measurement_state = measurement_state | MEASUREMENT_STATE::RADAR;
    }
  }
  // check CAMERA
  if (last_updated_time_map_.find(MEASUREMENT_STATE::CAMERA) != last_updated_time_map_.end()) {
    if ((current_time - last_updated_time_map_.at(MEASUREMENT_STATE::CAMERA)).seconds() < max_dt_) {
      measurement_state = measurement_state | MEASUREMENT_STATE::CAMERA;
    }
  }
  return measurement_state;
}

void TrackerState::updateWithLIDAR(
  const rclcpp::Time & current_time, const TrackedObject & tracked_object)
{
  // if radar is available, do not update velocity
  if (measurement_state_ & MEASUREMENT_STATE::RADAR) {
    // update tracked object
    updateWithFunction(
      MEASUREMENT_STATE::LIDAR, current_time, tracked_object, merger_utils::updateExceptVelocity);
  } else {
    // else just update tracked object
    updateWithFunction(
      MEASUREMENT_STATE::LIDAR, current_time, tracked_object,
      merger_utils::updateWholeTrackedObject);
  }
}

bool TrackerState::updateWithFunction(
  const MEASUREMENT_STATE input, const rclcpp::Time & current_time,
  const TrackedObject & input_tracked_object,
  std::function<void(TrackedObject &, const TrackedObject &)> update_func)
{
  // put input uuid and last update time
  if (current_time > last_update_time_) {
    const auto predict_successful = predict(current_time);
    if (!predict_successful) {
      return false;
    }
  }

  // update with measurement state
  last_updated_time_map_[input] = current_time;
  input_uuid_map_[input] = input_tracked_object.object_id;
  measurement_state_ = measurement_state_ | input;
  existence_probability_ =
    std::max(existence_probability_, default_existence_probability_map_[input]);

  // update tracked object
  update_func(tracked_object_, input_tracked_object);
  tracked_object_.object_id = const_uuid_;  // overwrite uuid to stay same
  return true;
}

bool TrackerState::predict(
  const double dt, std::function<TrackedObject(const TrackedObject &, double)> func)
{
  const auto predicted_object = func(tracked_object_, dt);
  tracked_object_ = predicted_object;
  return true;
}

void TrackerState::updateWithRADAR(
  const rclcpp::Time & current_time, const TrackedObject & tracked_object)
{
  // if lidar is available, update only velocity
  if (measurement_state_ & MEASUREMENT_STATE::LIDAR) {
    // update tracked object
    updateWithFunction(
      MEASUREMENT_STATE::RADAR, current_time, tracked_object,
      merger_utils::updateOnlyObjectVelocity);
  } else {
    // else just update tracked object
    updateWithFunction(
      MEASUREMENT_STATE::RADAR, current_time, tracked_object,
      merger_utils::updateWholeTrackedObject);
  }
}

